contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _owner) public payable {
        uint256 balBefore = address(c).balance;
        c.setOwner(_owner); if (__ESBMC_reverted()) return;
        assert(c.owner() == _owner && address(c).balance == balBefore);
    }

    receive() external payable {}
}

