pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address _owner) internal {
        uint256 balBefore = address(c).balance;
        try c.setOwner(_owner) {} catch { return; }
        assertTrue(c.owner() == _owner && address(c).balance == balBefore);
    }

    function testFuzz_run(address _owner) public {
        vm.assume(_owner.code.length == 0 && uint160(_owner) > 0xffff && _owner != address(this) && _owner != address(c) && _owner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _owner != 0x000000000000000000636F6e736F6c652e6c6f67 && _owner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _owner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_owner);
    }

    receive() external payable {}
}
